let raw = $json.text || "";

// Remove possible markdown code fences
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed = {};
let parseError = false;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  parseError = true;
}

const requiredFields = [
  "what_it_does",
  "why_it_matters",
  "category",
  "relevance_score",
  "learning_score",
  "novelty_score",
  "key_takeaways"
];

const missingFields = requiredFields.filter(
  field => parsed[field] === undefined || parsed[field] === null
);

const scoresValid =
  typeof parsed.relevance_score === "number" &&
  parsed.relevance_score >= 0 &&
  parsed.relevance_score <= 10 &&

  typeof parsed.learning_score === "number" &&
  parsed.learning_score >= 0 &&
  parsed.learning_score <= 10 &&

  typeof parsed.novelty_score === "number" &&
  parsed.novelty_score >= 0 &&
  parsed.novelty_score <= 10;

const contentValid =
  typeof parsed.what_it_does === "string" &&
  parsed.what_it_does.trim().length > 0 &&

  typeof parsed.why_it_matters === "string" &&
  parsed.why_it_matters.trim().length > 0 &&

  typeof parsed.category === "string" &&
  parsed.category.trim().length > 0 &&

  Array.isArray(parsed.key_takeaways) &&
  parsed.key_takeaways.length > 0;

const valid =
  !parseError &&
  missingFields.length === 0 &&
  scoresValid &&
  contentValid;

return {
  json: {
    valid_json: valid,

    what_it_does: parsed.what_it_does || "",
    why_it_matters: parsed.why_it_matters || "",
    category: parsed.category || "",

    relevance_score: parsed.relevance_score ?? 0,
    learning_score: parsed.learning_score ?? 0,
    novelty_score: parsed.novelty_score ?? 0,

    key_takeaways: Array.isArray(parsed.key_takeaways)
      ? parsed.key_takeaways
      : [],

    missing_fields: missingFields
  }
};
